#!/usr/bin/env python3
"""Dependency-free static build. Evidence lives in research/findings.json."""
import json, html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'research/findings.json').read_text())
e=html.escape
sections=data['sections']; sources=data['sources']
nav=[('index.html','Overview')]+[(f"pages/{s['slug']}.html",s['title']) for s in sections]+[('pages/sources.html','Sources & method')]
def source_links(ids):
    return '<br>'.join(f'<a href="{e(sources[x]["url"])}">{e(x)} · {e(sources[x]["short"])}</a>' for x in ids)
def table(rows):
    out='<div class="table-wrap"><table><thead><tr><th scope="col">Entry</th><th scope="col">Confirmed rule / finding</th><th scope="col">Application & limits</th><th scope="col">Evidence</th></tr></thead><tbody>'
    for r in rows:
        cls='review' if r['status']=='Needs review' else 'confirmed'
        out+=f'<tr id="{e(r["id"])}"><th scope="row"><small>{e(r["id"])}</small>{e(r["title"])}<span class="badge {cls}">{e(r["status"])}</span></th><td>{e(r["value"])}{("<em class=empty>Unverified — no confirmed value</em>" if not r["value"] else "")}</td><td>{e(r["note"])}</td><td>{source_links(r["sources"])}<details><summary>Evidence note</summary><p>{e(r["evidence"])}</p></details></td></tr>'
    return out+'</tbody></table></div>'
def shell(title,desc,body,current,sub=True):
    prefix='../' if sub else ''
    navigation=''.join(f'<a {"aria-current=page" if current==url else ""} href="{prefix}{url}">{e(label)}</a>' for url,label in nav)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(desc)}"><title>{e(title)} · California Coverage Guide</title><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="{prefix}index.html"><span class="brand-icon">+</span> California<br><strong>Coverage Guide</strong></a><p class="sidebar-label">RESEARCH DASHBOARD</p><nav aria-label="Main navigation">{navigation}</nav><div class="sidebar-foot">Official-source research<br>Re-verified 19 October 2026<br><span>Independent guide · not a government site</span></div></aside><div class="workspace"><header><span>HEALTHCARE / CALIFORNIA</span><span class="date">Evidence re-checked · 19 Oct 2026</span></header><main id="main"><div class="eyebrow">COVERAGE WITHOUT WAGES</div><h1>{e(title)}</h1><p class="lede">{e(desc)}</p>{body}</main><footer>Research snapshot, not an eligibility decision or legal/tax advice. County eligibility staff determine Medi-Cal eligibility. No personal financial data is collected. Official materials can change after this review.</footer></div></body></html>'''
for s in sections:
    body=f'<div class="notice">{e(s["intro"])}</div><div class="table-tools"><h2>{len(s["rows"])} evidence-linked entries</h2><label>Filter this table <input type="search" placeholder="Search findings…" aria-label="Filter findings"></label><button type="button" onclick="window.print()">Print / save PDF</button></div><p class="filter-count" aria-live="polite"></p>'+table(s['rows'])
    (ROOT/f'pages/{s["slug"]}.html').write_text(shell(s['title'],s['description'],body,f'pages/{s["slug"]}.html'))
summary=data['summary']
body='''<div class="hero-callout"><span class="tag">THE SHORT ANSWER</span><h2>$0 earned income does not automatically mean you fail.</h2><p>The income route is not wages-only. Countable rental and interest income can matter for both the $580 community-engagement threshold and Medi-Cal’s separate upper income limit. Your actual eligibility is not established here.</p><a class="button" href="pages/income.html">Understand your income <span aria-hidden="true">→</span></a><a class="text-link" href="pages/work-rules.html">Read the new rules</a></div><div class="metrics"><div><span>Income pathway</span><strong>$580 / month</strong><small>Federal minimum wage × 80; see E1 / W3</small></div><div><span>Activity pathway</span><strong>80 hours</strong><small>Or at least half-time education; see W4–W7</small></div><div><span>Timing needs care</span><strong>2027</strong><small>Official date discrepancy; see F1</small></div></div><div class="notice warning"><strong>Do not assume “no earned income” means “no income.”</strong> Rental profit, interest, and countable trading income can affect financial eligibility. Do not report $0 total income solely because you have no wages. Kalshi-specific classification and your personal figures remain unverified.</div><div class="section-heading"><div><div class="eyebrow">EXECUTIVE SUMMARY</div><h2>Your coverage decision map</h2></div><span>Start here, then explore the evidence</span></div>'''+table(summary)
body+='<div class="section-heading"><h2>Explore the research</h2></div><div class="cards">'+''.join(f'<a class="card" href="pages/{s["slug"]}.html"><span>{i+1:02}</span><h3>{e(s["title"])}</h3><p>{e(s["description"])}</p><b>{len(s["rows"])} entries →</b></a>' for i,s in enumerate(sections))+'</div>'
(ROOT/'index.html').write_text(shell('Healthcare without earned income','A practical, evidence-linked guide for a U.S. citizen residing in California, with rental income, savings interest, and own-account trading.',body,'index.html',False))
source_rows=[dict(id=k,title=v['short'],status='Source reviewed',value=v['title'],note=v['locator'],sources=[k],evidence=v['excerpt']) for k,v in sources.items()]
method='''<div class="notice">Scope: Medi-Cal adult-expansion work/community engagement rules and coverage alternatives relevant to the stated income sources. This is not an exhaustive tax opinion, a list of all insurers, or a guarantee of future eligibility. The repository initially contained only a one-line README; there was no pre-existing healthcare dataset to audit. Re-verification on October 19, 2026 (arena/75b1956e) re-fetched every source below and re-read each row against it. It added the enacted California statute (AB 2161), 42 CFR 435.552, the federal seasonal-worker definition and Covered California’s 2027 chart.</div><h2>How this was checked</h2><ol class="method"><li>Read official DHCS, CMS/Medicaid.gov, HealthCare.gov, Covered California and IRS materials via retrieved page text; use targeted official-document search evidence where identified below.</li><li>Map every finding to an official source, with a locator and evidence note. “Official rule” means the general statement is supported, not that a person has been approved. “Conditional” identifies analysis dependent on facts not supplied.</li><li>Leave unconfirmed values blank on Flagged for Review. A source linked to a flagged row supports the context, not the unresolved answer. No Kalshi-specific conclusion is inferred from general securities guidance.</li><li>Check local navigation, assets, source-domain allowlist, unique row IDs and evidence completeness automatically. External pages were retrieved or located in official search results on the review date, not continuously monitored. Automated external HTTP link checks are restricted by sandbox egress; no blanket external-link guarantee is made.</li><li>Use the current federal rule and correction with newer California guidance. Do not silently harmonize conflicting official dates, income wording, or rounded thresholds.</li></ol><h2>Source register</h2>'''
(ROOT/'pages/sources.html').write_text(shell('Sources & method','Review the primary evidence, exact locators, verification scope, and limitations.',method+table(source_rows),'pages/sources.html'))
print(f'Built {len(sections)+2} pages with {sum(len(s["rows"]) for s in sections)+len(summary)} finding rows and {len(sources)} sources.')
